    --md-sys-typescale-headline-large-font-size: 32px;
    --md-sys-typescale-headline-large-font-weight: 400;
    --md-sys-typescale-headline-medium-font-size: 28px;
    --md-sys-typescale-headline-medium-font-weight: 400;
    --md-sys-typescale-headline-small-font-size: 24px;
    --md-sys-typescale-headline-small-font-weight: 400;
    --md-sys-typescale-title-large-font-size: 22px;
    --md-sys-typescale-title-large-font-weight: 500;
    --md-sys-typescale-title-medium-font-size: 16px;
    --md-sys-typescale-title-medium-font-weight: 500;
    --md-sys-typescale-title-small-font-size: 14px;
    --md-sys-typescale-title-small-font-weight: 500;
    --md-sys-typescale-body-large-font-size: 16px;
    --md-sys-typescale-body-large-font-weight: 400;
    --md-sys-typescale-body-medium-font-size: 14px;
    --md-sys-typescale-body-medium-font-weight: 400;
    --md-sys-typescale-body-small-font-size: 12px;
    --md-sys-typescale-body-small-font-weight: 400;
    --md-sys-typescale-label-large-font-size: 14px;
    --md-sys-typescale-label-large-font-weight: 500;
    --md-sys-typescale-label-medium-font-size: 12px;
    --md-sys-typescale-label-medium-font-weight: 500;
    --md-sys-typescale-label-small-font-size: 11px;
    --md-sys-typescale-label-small-font-weight: 500;

    /* Spacing */
    --md-sys-spacing-0: 0;
    --md-sys-spacing-1: 4px;
    --md-sys-spacing-2: 8px;
    --md-sys-spacing-3: 12px;
    --md-sys-spacing-4: 16px;
    --md-sys-spacing-5: 20px;
    --md-sys-spacing-6: 24px;
    --md-sys-spacing-7: 28px;
    --md-sys-spacing-8: 32px;

    /* Shadows */
    --md-sys-shadow-1: 0 1px 3px rgba(0, 0, 0, 0.12), 0 1px 2px rgba(0, 0, 0, 0.24);
    --md-sys-shadow-2: 0 3px 6px rgba(0, 0, 0, 0.16), 0 3px 6px rgba(0, 0, 0, 0.23);
    --md-sys-shadow-3: 0 10px 20px rgba(0, 0, 0, 0.19), 0 6px 6px rgba(0, 0, 0, 0.23);
    --md-sys-shadow-4: 0 15px 25px rgba(0, 0, 0, 0.15), 0 5px 10px rgba(0, 0, 0, 0.05);

    /* Border radius */
    --md-sys-shape-corner-extra-small: 4px;
    --md-sys-shape-corner-small: 8px;
    --md-sys-shape-corner-medium: 12px;
    --md-sys-shape-corner-large: 16px;
    --md-sys-shape-corner-extra-large: 28px;

    /* Legacy backwards compatibility */
    --primary-color: var(--md-sys-color-primary);
    --primary-dark: var(--md-sys-color-on-primary-container);
    --success-color: var(--md-sys-color-tertiary);
    --danger-color: var(--md-sys-color-error);
    --warning-color: var(--md-sys-color-warning);
    --border-color: var(--md-sys-color-outline);
    --bg-light: var(--md-sys-color-surface-variant);
    --text-dark: var(--md-sys-color-on-background);
    --text-muted: var(--md-sys-color-on-surface-variant);
    --sidebar-width: 250px;
}

/* Dark Mode */
@media (prefers-color-scheme: dark) {
    :root {
        /* Dark Mode - Primary Colors */
        --md-sys-color-primary: #90CAF9;
        --md-sys-color-on-primary: #0D47A1;
        --md-sys-color-primary-container: #1565C0;
        --md-sys-color-on-primary-container: #E3F2FD;

        /* Dark Mode - Secondary */
        --md-sys-color-secondary: #64B5F6;
        --md-sys-color-on-secondary: #0D47A1;
        --md-sys-color-secondary-container: #1565C0;
        --md-sys-color-on-secondary-container: #E3F2FD;

        /* Dark Mode - Tertiary */
        --md-sys-color-tertiary: #81C784;
        --md-sys-color-on-tertiary: #1B5E20;
        --md-sys-color-tertiary-container: #2E7D32;
        --md-sys-color-on-tertiary-container: #C8E6C9;

        /* Dark Mode - Error */
        --md-sys-color-error: #EF5350;
        --md-sys-color-on-error: #C62828;
        --md-sys-color-error-container: #B71C1C;
        --md-sys-color-on-error-container: #FFCDD2;

        /* Dark Mode - Surfaces */
        --md-sys-color-background: #121212;
        --md-sys-color-surface: #1E1E1E;
        --md-sys-color-surface-variant: #2C2C2C;
        --md-sys-color-surface-dim: #0A0A0A;
        --md-sys-color-on-background: #E1E1E1;
        --md-sys-color-on-surface: #E1E1E1;
        --md-sys-color-on-surface-variant: #9E9E9E;

        /* Dark Mode - Outline */
        --md-sys-color-outline: #424242;
        --md-sys-color-outline-variant: #616161;
    }
}

/* Override dark mode for explicit dark theme class */
[data-theme="dark"] {
    --md-sys-color-primary: #90CAF9;
    --md-sys-color-on-primary: #0D47A1;
    --md-sys-color-primary-container: #1565C0;
    --md-sys-color-on-primary-container: #E3F2FD;
    --md-sys-color-secondary: #64B5F6;
    --md-sys-color-on-secondary: #0D47A1;
    --md-sys-color-secondary-container: #1565C0;
    --md-sys-color-on-secondary-container: #E3F2FD;
    --md-sys-color-tertiary: #81C784;
    --md-sys-color-on-tertiary: #1B5E20;
    --md-sys-color-tertiary-container: #2E7D32;
    --md-sys-color-on-tertiary-container: #C8E6C9;
    --md-sys-color-error: #EF5350;
    --md-sys-color-on-error: #C62828;
    --md-sys-color-error-container: #B71C1C;
    --md-sys-color-on-error-container: #FFCDD2;
    --md-sys-color-background: #121212;
    --md-sys-color-surface: #1E1E1E;
    --md-sys-color-surface-variant: #2C2C2C;
    --md-sys-color-surface-dim: #0A0A0A;
    --md-sys-color-on-background: #E1E1E1;
    --md-sys-color-on-surface: #E1E1E1;
    --md-sys-color-on-surface-variant: #9E9E9E;
    --md-sys-color-outline: #424242;
    --md-sys-color-outline-variant: #616161;
}

/* ===== Global Styles ===== */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: 'Inter', 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    font-size: var(--md-sys-typescale-body-large-font-size);
    font-weight: var(--md-sys-typescale-body-large-font-weight);
    line-height: 1.6;
    color: var(--md-sys-color-on-background);
    background-color: var(--md-sys-color-background);
    transition: background-color 0.3s ease, color 0.3s ease;
}

a {
    color: var(--md-sys-color-primary);
    text-decoration: none;
    transition: color 0.2s ease;
}

a:hover {
    color: var(--md-sys-color-secondary);
}

/* Typography Scale */
.display-large {
    font-size: var(--md-sys-typescale-display-large-font-size);
    font-weight: var(--md-sys-typescale-display-large-font-weight);
}

.display-medium {
    font-size: var(--md-sys-typescale-display-medium-font-size);
    font-weight: var(--md-sys-typescale-display-medium-font-weight);
}

.headline-large {
    font-size: var(--md-sys-typescale-headline-large-font-size);
    font-weight: var(--md-sys-typescale-headline-large-font-weight);
}

.headline-medium {
    font-size: var(--md-sys-typescale-headline-medium-font-size);
    font-weight: var(--md-sys-typescale-headline-medium-font-weight);
}

.headline-small {
    font-size: var(--md-sys-typescale-headline-small-font-size);
    font-weight: var(--md-sys-typescale-headline-small-font-weight);
}

.title-large {
    font-size: var(--md-sys-typescale-title-large-font-size);
    font-weight: var(--md-sys-typescale-title-large-font-weight);
}

.title-medium {
    font-size: var(--md-sys-typescale-title-medium-font-size);
    font-weight: var(--md-sys-typescale-title-medium-font-weight);
}

.title-small {
    font-size: var(--md-sys-typescale-title-small-font-size);
    font-weight: var(--md-sys-typescale-title-small-font-weight);
}

.body-large {
    font-size: var(--md-sys-typescale-body-large-font-size);
    font-weight: var(--md-sys-typescale-body-large-font-weight);
}

.body-medium {
    font-size: var(--md-sys-typescale-body-medium-font-size);
    font-weight: var(--md-sys-typescale-body-medium-font-weight);
}

.body-small {
    font-size: var(--md-sys-typescale-body-small-font-size);
    font-weight: var(--md-sys-typescale-body-small-font-weight);
}

.label-large {
    font-size: var(--md-sys-typescale-label-large-font-size);
    font-weight: var(--md-sys-typescale-label-large-font-weight);
}

.label-medium {
    font-size: var(--md-sys-typescale-label-medium-font-size);
    font-weight: var(--md-sys-typescale-label-medium-font-weight);
}

.label-small {
    font-size: var(--md-sys-typescale-label-small-font-size);
    font-weight: var(--md-sys-typescale-label-small-font-weight);
}

/* ===== Flash Messages ===== */

.flash-messages-container {
    position: fixed;
    top: var(--md-sys-spacing-5);
    right: var(--md-sys-spacing-5);
    z-index: 1000;
    max-width: 400px;
    display: flex;
    flex-direction: column;
    gap: var(--md-sys-spacing-2);
}

.alert {
    padding: var(--md-sys-spacing-4);
    border-radius: var(--md-sys-shape-corner-medium);
    box-shadow: var(--md-sys-shadow-2);
    display: flex;
    justify-content: space-between;
    align-items: center;
    animation: slideInRight 0.3s ease-out;
    font-size: var(--md-sys-typescale-body-medium-font-size);
}

.alert-success {
    background-color: var(--md-sys-color-tertiary-container);
    color: var(--md-sys-color-on-tertiary-container);
    border-left: 4px solid var(--md-sys-color-tertiary);
}

.alert-error {
    background-color: var(--md-sys-color-error-container);
    color: var(--md-sys-color-on-error-container);
    border-left: 4px solid var(--md-sys-color-error);
}

.alert-warning {
    background-color: var(--md-sys-color-warning-container);
    color: var(--md-sys-color-on-warning-container);
    border-left: 4px solid var(--md-sys-color-warning);
}

.alert-info {
    background-color: var(--md-sys-color-primary-container);
    color: var(--md-sys-color-on-primary-container);
    border-left: 4px solid var(--md-sys-color-primary);
}

.alert-close-btn {
    background: none;
    border: none;
    font-size: 20px;
    cursor: pointer;
    color: inherit;
    opacity: 0.7;
    transition: opacity 0.2s;
}

.alert-close-btn:hover {
    opacity: 1;
}

@keyframes slideInRight {
    from {
        transform: translateX(100%);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

/* ===== Authentication ===== */

.auth-page-wrapper,
.auth-container {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 50%, #f093fb 100%);
    background-attachment: fixed;
    padding: var(--md-sys-spacing-4);
    position: relative;
    overflow: hidden;
}

.auth-page-wrapper::before,
.auth-container::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(255, 255, 255, 0.1) 1px, transparent 1px);
    background-size: 50px 50px;
    animation: drift 20s linear infinite;
}

@keyframes drift {
    0% { transform: translate(0, 0); }
    100% { transform: translate(50px, 50px); }
}

.auth-card-wrapper,
.auth-card {
    background: var(--md-sys-color-surface);
    padding: var(--md-sys-spacing-8);
    border-radius: 20px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    width: 100%;
    max-width: 480px;
    display: flex;
    flex-direction: column;
    position: relative;
    z-index: 1;
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.2);
    animation: slideUp 0.6s ease-out;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.auth-card-header,
.auth-header {
    text-align: center;
    margin-bottom: var(--md-sys-spacing-8);
    padding-bottom: var(--md-sys-spacing-6);
    border-bottom: 2px solid var(--md-sys-color-outline);
}

.auth-card-header h1,
.auth-header h1 {
    font-size: 42px;
    font-weight: 700;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: var(--md-sys-spacing-2);
}

.auth-card-header p,
.auth-header p {
    font-size: var(--md-sys-typescale-body-medium-font-size);
    color: var(--md-sys-color-on-surface-variant);
    margin: 0;
    font-weight: 500;
    letter-spacing: 0.5px;
}

.auth-form-container h2,
.auth-form h2 {
    font-size: 28px;
    font-weight: 600;
    margin-bottom: var(--md-sys-spacing-6);
    color: var(--md-sys-color-on-surface);
}

.auth-form {
    display: flex;
    flex-direction: column;
}

.auth-form .form-group {
    margin-bottom: var(--md-sys-spacing-5);
    animation: fadeInUp 0.6s ease-out forwards;
    opacity: 0;
}

.auth-form .form-group:nth-child(1) { animation-delay: 0.1s; }
.auth-form .form-group:nth-child(2) { animation-delay: 0.2s; }

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.auth-form .form-group label {
    font-size: var(--md-sys-typescale-label-large-font-size);
    font-weight: 600;
    color: var(--md-sys-color-on-surface);
    margin-bottom: var(--md-sys-spacing-2);
    display: flex;
    align-items: center;
    gap: var(--md-sys-spacing-2);
}

.auth-form .form-group input {
    padding: var(--md-sys-spacing-4) var(--md-sys-spacing-5);
    border: 2px solid var(--md-sys-color-outline);
    border-radius: 12px;
    font-size: var(--md-sys-typescale-body-large-font-size);
    background: var(--md-sys-color-background);
    color: var(--md-sys-color-on-surface);
    transition: all 0.3s ease;
}

.auth-form .form-group input:hover {
    border-color: var(--md-sys-color-primary);
    background: var(--md-sys-color-surface);
}

.auth-form .form-group input:focus {
    outline: none;
    border-color: var(--md-sys-color-primary);
    box-shadow: 0 0 0 4px rgba(102, 126, 234, 0.1);
    background: var(--md-sys-color-surface);
}

.auth-form .btn {
    padding: var(--md-sys-spacing-4) var(--md-sys-spacing-6);
    border-radius: 12px;
    font-size: 16px;
    font-weight: 600;
    margin-top: var(--md-sys-spacing-6);
    margin-bottom: var(--md-sys-spacing-4);
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    cursor: pointer;
    transition: all 0.3s ease;
    box-shadow: 0 8px 20px rgba(102, 126, 234, 0.3);
    animation: fadeInUp 0.6s ease-out 0.3s forwards;
    opacity: 0;
}

.auth-form .btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 30px rgba(102, 126, 234, 0.4);
}

.auth-form .btn:active {
    transform: translateY(0);
    box-shadow: 0 6px 15px rgba(102, 126, 234, 0.3);
}

.auth-card-footer,
.auth-footer {
    margin-top: var(--md-sys-spacing-6);
    padding-top: var(--md-sys-spacing-6);
    border-top: 1px solid var(--md-sys-color-outline);
    text-align: center;
}

.auth-footer p {
    font-size: var(--md-sys-typescale-body-small-font-size);
    color: var(--md-sys-color-on-surface-variant);
    margin: var(--md-sys-spacing-2) 0;
}

.auth-card-footer a,
.auth-footer a {
    color: var(--md-sys-color-primary);
    font-weight: 600;
    text-decoration: none;
    transition: all 0.2s ease;
    position: relative;
}

.auth-card-footer a::after,
.auth-footer a::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    transition: width 0.3s ease;
}

.auth-card-footer a:hover::after,
.auth-footer a:hover::after {
    width: 100%;
}

.text-muted {
    color: var(--md-sys-color-on-surface-variant) !important;
    font-size: 12px;
    letter-spacing: 0.5px;
}

/* ===== Admin Layout ===== */

.admin-page-wrapper {
    display: flex;
    min-height: 100vh;
    background-color: var(--md-sys-color-background);
}

.admin-sidebar {
    width: var(--sidebar-width);
    background: linear-gradient(180deg, #1e293b 0%, #0f172a 100%);
    color: white;
    display: flex;
    flex-direction: column;
    position: fixed;
    height: 100vh;
    overflow-y: auto;
    box-shadow: var(--md-sys-shadow-1);
    z-index: 100;
}

.sidebar-brand {
    padding: var(--md-sys-spacing-5);
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.sidebar-brand h2 {
    font-size: var(--md-sys-typescale-title-large-font-size);
    margin-bottom: var(--md-sys-spacing-1);
    color: var(--md-sys-color-primary);
}

.sidebar-brand p {
    font-size: var(--md-sys-typescale-label-medium-font-size);
    color: rgba(255, 255, 255, 0.7);
    margin: 0;
}

.sidebar-nav-menu {
    list-style: none;
    padding: var(--md-sys-spacing-3) 0;
    flex: 1;
}

.sidebar-nav-menu li {
    margin-bottom: var(--md-sys-spacing-1);
}

.sidebar-nav-link {
    display: flex;
    align-items: center;
    gap: var(--md-sys-spacing-3);
    padding: var(--md-sys-spacing-3) var(--md-sys-spacing-5);
    color: rgba(255, 255, 255, 0.7);
    text-decoration: none;
    transition: all 0.2s ease;
    font-size: var(--md-sys-typescale-body-medium-font-size);
}

.sidebar-nav-link:hover {
    background: rgba(255, 255, 255, 0.1);
    color: white;
}

.sidebar-nav-link.active {
    background: var(--md-sys-color-primary);
    color: var(--md-sys-color-on-primary);
    border-left: 4px solid var(--md-sys-color-tertiary);
    padding-left: calc(var(--md-sys-spacing-5) - 4px);
}

.sidebar-nav-icon {
    font-size: 20px;
}

.sidebar-footer {
    padding: var(--md-sys-spacing-4) var(--md-sys-spacing-5);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.sidebar-user-info {
    display: flex;
    align-items: center;
    gap: var(--md-sys-spacing-3);
    padding-bottom: var(--md-sys-spacing-3);
}

.sidebar-user-avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: var(--md-sys-color-primary);
    color: white;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
}

.sidebar-user-name {
    font-size: var(--md-sys-typescale-label-large-font-size);
    color: white;
}

.sidebar-user-role {
    font-size: var(--md-sys-typescale-label-small-font-size);
    color: rgba(255, 255, 255, 0.7);
}

.admin-main-content {
    margin-left: var(--sidebar-width);
    flex: 1;
    padding: var(--md-sys-spacing-8);
    background: var(--md-sys-color-background);
    min-height: 100vh;
}

/* ===== User Layout ===== */

.user-page-wrapper {
    background: var(--md-sys-color-background);
    min-height: 100vh;
}

.user-topbar {
    background: var(--md-sys-color-surface);
    padding: var(--md-sys-spacing-4) var(--md-sys-spacing-8);
    box-shadow: var(--md-sys-shadow-1);
    display: flex;
    justify-content: space-between;
    align-items: center;
    sticky: top;
    z-index: 50;
}

.topbar-brand h2 {
    color: var(--md-sys-color-primary);
    margin: 0;
    font-size: var(--md-sys-typescale-title-large-font-size);
}

.topbar-brand p {
    font-size: var(--md-sys-typescale-label-medium-font-size);
    color: var(--md-sys-color-on-surface-variant);
    margin: 0;
}

.topbar-user-menu {
    display: flex;
    align-items: center;
    gap: var(--md-sys-spacing-4);
}

.topbar-logout-btn {
    background: var(--md-sys-color-error);
    color: var(--md-sys-color-on-error);
    padding: var(--md-sys-spacing-2) var(--md-sys-spacing-4);
    border-radius: var(--md-sys-shape-corner-small);
    border: none;
    cursor: pointer;
    font-size: var(--md-sys-typescale-label-large-font-size);
    transition: all 0.2s ease;
}

.topbar-logout-btn:hover {
    background: var(--md-sys-color-error-container);
    color: var(--md-sys-color-on-error-container);
}

/* ===== Container ===== */

.page-container {
    max-width: 1280px;
    margin: 0 auto;
    padding: var(--md-sys-spacing-6);
}

/* ===== Page Header ===== */

.page-header-wrapper {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--md-sys-spacing-8);
    flex-wrap: wrap;
    gap: var(--md-sys-spacing-4);
}

.page-header-wrapper h1 {
    font-size: var(--md-sys-typescale-headline-medium-font-size);
    color: var(--md-sys-color-on-background);
    margin: 0;
}

.page-header-actions {
    display: flex;
    gap: var(--md-sys-spacing-3);
    flex-wrap: wrap;
}

/* ===== Buttons ===== */

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--md-sys-spacing-2);
    padding: var(--md-sys-spacing-3) var(--md-sys-spacing-6);
    border: none;
    border-radius: var(--md-sys-shape-corner-medium);
    cursor: pointer;
    font-size: var(--md-sys-typescale-label-large-font-size);
    font-weight: 500;
    text-decoration: none;
    transition: all 0.2s ease;
    white-space: nowrap;
}

.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.btn-primary {
    background: var(--md-sys-color-primary);
    color: var(--md-sys-color-on-primary);
}

.btn-primary:hover:not(:disabled) {
    background: var(--md-sys-color-primary-container);
    color: var(--md-sys-color-on-primary-container);
    box-shadow: var(--md-sys-shadow-2);
}

.btn-secondary {
    background: var(--md-sys-color-secondary);
    color: var(--md-sys-color-on-secondary);
}

.btn-secondary:hover:not(:disabled) {
    background: var(--md-sys-color-secondary-container);
    color: var(--md-sys-color-on-secondary-container);
    box-shadow: var(--md-sys-shadow-2);
}

.btn-success {
    background: var(--md-sys-color-tertiary);
    color: var(--md-sys-color-on-tertiary);
}

.btn-success:hover:not(:disabled) {
    background: var(--md-sys-color-tertiary-container);
    color: var(--md-sys-color-on-tertiary-container);
    box-shadow: var(--md-sys-shadow-2);
}

.btn-danger {
    background: var(--md-sys-color-error);
    color: var(--md-sys-color-on-error);
}

.btn-danger:hover:not(:disabled) {
    background: var(--md-sys-color-error-container);
    color: var(--md-sys-color-on-error-container);
    box-shadow: var(--md-sys-shadow-2);
}

.btn-outline {
    background: transparent;
    border: 1px solid var(--md-sys-color-outline);
    color: var(--md-sys-color-primary);
}

.btn-outline:hover:not(:disabled) {
    background: var(--md-sys-color-primary-container);
    border-color: var(--md-sys-color-primary);
}

.btn-text {
    background: transparent;
    color: var(--md-sys-color-primary);
}

.btn-text:hover:not(:disabled) {
    background: var(--md-sys-color-primary-container);
}

.btn-sm {
    padding: var(--md-sys-spacing-2) var(--md-sys-spacing-4);
    font-size: var(--md-sys-typescale-label-medium-font-size);
}

.btn-lg {
    padding: var(--md-sys-spacing-4) var(--md-sys-spacing-8);
    font-size: var(--md-sys-typescale-label-large-font-size);
    min-height: 44px;
}

.btn-block {
    display: block;
    width: 100%;
}

.btn-icon {
    width: 40px;
    height: 40px;
    padding: var(--md-sys-spacing-2);
    border-radius: var(--md-sys-shape-corner-small);
}

/* ===== Forms ===== */

.form-wrapper {
    background: var(--md-sys-color-surface);
    padding: var(--md-sys-spacing-8);
    border-radius: var(--md-sys-shape-corner-large);
    box-shadow: var(--md-sys-shadow-1);
}

.form-group {
    margin-bottom: var(--md-sys-spacing-6);
}

.form-group-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--md-sys-spacing-6);
}

.form-label,
.form-group label {
    display: block;
    margin-bottom: var(--md-sys-spacing-2);
    font-weight: 500;
    font-size: var(--md-sys-typescale-label-large-font-size);
    color: var(--md-sys-color-on-surface);
}

.form-label-required::after {
    content: ' *';
    color: var(--md-sys-color-error);
}

.form-input,
.form-select,
.form-textarea,
.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    padding: var(--md-sys-spacing-3) var(--md-sys-spacing-4);
    border: 1px solid var(--md-sys-color-outline);
    border-radius: var(--md-sys-shape-corner-small);
    font-size: var(--md-sys-typescale-body-large-font-size);
    font-family: inherit;
    background: var(--md-sys-color-surface);
    color: var(--md-sys-color-on-surface);
    transition: all 0.2s ease;
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus,
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: var(--md-sys-color-primary);
    box-shadow: 0 0 0 3px var(--md-sys-color-primary-container);
}

.form-input::placeholder {
    color: var(--md-sys-color-on-surface-variant);
}

.form-textarea {
    resize: vertical;
    min-height: 120px;
}

.form-helper-text {
    font-size: var(--md-sys-typescale-label-small-font-size);
    color: var(--md-sys-color-on-surface-variant);
    margin-top: var(--md-sys-spacing-1);
}

.form-error-text {
    font-size: var(--md-sys-typescale-label-small-font-size);
    color: var(--md-sys-color-error);
    margin-top: var(--md-sys-spacing-1);
}

.form-group.has-error .form-input,
.form-group.has-error .form-select,
.form-group.has-error .form-textarea {
    border-color: var(--md-sys-color-error);
}

.checkbox-wrapper,
.radio-wrapper {
    display: flex;
    align-items: center;
    gap: var(--md-sys-spacing-3);
    margin-bottom: var(--md-sys-spacing-3);
    cursor: pointer;
}

.checkbox-input,
.radio-input {
    cursor: pointer;
}

.form-actions {
    display: flex;
    gap: var(--md-sys-spacing-4);
    justify-content: center;
    margin-top: var(--md-sys-spacing-8);
}

/* ===== Tables ===== */

.table-wrapper {
    background: var(--md-sys-color-surface);
    border-radius: var(--md-sys-shape-corner-large);
    box-shadow: var(--md-sys-shadow-1);
    overflow: hidden;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: var(--md-sys-typescale-body-medium-font-size);
}

.data-table thead {
    background: var(--md-sys-color-surface-variant);
}

.data-table th {
    padding: var(--md-sys-spacing-4);
    text-align: left;
    font-weight: 600;
    color: var(--md-sys-color-on-surface);
    border-bottom: 2px solid var(--md-sys-color-outline);
}

.data-table td {
    padding: var(--md-sys-spacing-4);
    border-bottom: 1px solid var(--md-sys-color-outline);
    color: var(--md-sys-color-on-surface);
}

.data-table tbody tr:hover {
    background: var(--md-sys-color-surface-variant);
}

.data-table tbody tr:nth-child(even) {
    background: rgba(0, 0, 0, 0.02);
}

/* Dark mode table striping */
[data-theme="dark"] .data-table tbody tr:nth-child(even) {
    background: rgba(255, 255, 255, 0.02);
}

.table-actions {
    display: flex;
    gap: var(--md-sys-spacing-2);
    justify-content: flex-end;
}

.table-action-btn {
    padding: var(--md-sys-spacing-2);
    background: transparent;
    border: none;
    cursor: pointer;
    font-size: 16px;
    transition: all 0.2s ease;
}

.table-action-btn:hover {
    color: var(--md-sys-color-primary);
}

/* ===== Cards ===== */

.card {
    background: var(--md-sys-color-surface);
    border-radius: var(--md-sys-shape-corner-large);
    box-shadow: var(--md-sys-shadow-1);
    padding: var(--md-sys-spacing-6);
    transition: all 0.2s ease;
}

.card:hover {
    box-shadow: var(--md-sys-shadow-2);
}

.card-header {
    font-size: var(--md-sys-typescale-title-large-font-size);
    font-weight: 600;
    color: var(--md-sys-color-on-surface);
    margin-bottom: var(--md-sys-spacing-4);
}

.card-body {
    font-size: var(--md-sys-typescale-body-medium-font-size);
    color: var(--md-sys-color-on-surface);
}

/* ===== Stats Cards ===== */

.stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--md-sys-spacing-6);
    margin-bottom: var(--md-sys-spacing-8);
}

.stat-card {
    background: var(--md-sys-color-surface);
    padding: var(--md-sys-spacing-6);
    border-radius: var(--md-sys-shape-corner-large);
    box-shadow: var(--md-sys-shadow-1);
    display: flex;
    align-items: flex-start;
    gap: var(--md-sys-spacing-4);
}

.stat-card-icon {
    font-size: 40px;
    min-width: 40px;
}

.stat-card-content {
    flex: 1;
}

.stat-card-number {
    font-size: 32px;
    font-weight: 700;
    color: var(--md-sys-color-primary);
    margin-bottom: var(--md-sys-spacing-1);
}

.stat-card-label {
    font-size: var(--md-sys-typescale-body-medium-font-size);
    color: var(--md-sys-color-on-surface-variant);
}

.stat-card-action {
    color: var(--md-sys-color-primary);
    text-decoration: none;
    font-size: var(--md-sys-typescale-label-medium-font-size);
    font-weight: 500;
    transition: all 0.2s ease;
}

.stat-card-action:hover {
    text-decoration: underline;
}

/* ===== Modals ===== */

.modal-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1000;
    align-items: center;
    justify-content: center;
    padding: var(--md-sys-spacing-4);
}

.modal-overlay.open {
    display: flex;
}

.modal-dialog {
    background: var(--md-sys-color-surface);
    border-radius: var(--md-sys-shape-corner-large);
    width: 90%;
    max-width: 600px;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: var(--md-sys-shadow-4);
    display: flex;
    flex-direction: column;
}

.modal-header {
    padding: var(--md-sys-spacing-6);
    border-bottom: 1px solid var(--md-sys-color-outline);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.modal-title {
    font-size: var(--md-sys-typescale-title-large-font-size);
    font-weight: 600;
    color: var(--md-sys-color-on-surface);
    margin: 0;
}

.modal-close-btn {
    background: none;
    border: none;
    font-size: 24px;
    cursor: pointer;
    color: var(--md-sys-color-on-surface-variant);
    transition: color 0.2s ease;
}

.modal-close-btn:hover {
    color: var(--md-sys-color-on-surface);
}

.modal-body {
    padding: var(--md-sys-spacing-6);
    flex: 1;
    overflow-y: auto;
}

.modal-footer {
    padding: var(--md-sys-spacing-6);
    border-top: 1px solid var(--md-sys-color-outline);
    display: flex;
    justify-content: flex-end;
    gap: var(--md-sys-spacing-4);
}

/* ===== Progress & Steps ===== */

.progress-bar {
    width: 100%;
    height: 8px;
    background: var(--md-sys-color-outline);
    border-radius: var(--md-sys-shape-corner-extra-small);
    overflow: hidden;
}

.progress-bar-fill {
    height: 100%;
    background: var(--md-sys-color-primary);
    transition: width 0.3s ease;
    border-radius: var(--md-sys-shape-corner-extra-small);
}

.stepper-wrapper {
    background: var(--md-sys-color-surface);
    padding: var(--md-sys-spacing-6);
    border-radius: var(--md-sys-shape-corner-large);
    box-shadow: var(--md-sys-shadow-1);
    margin-bottom: var(--md-sys-spacing-8);
}

.stepper {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
}

.step:not(:last-child)::after {
    content: '';
    position: absolute;
    top: 20px;
    left: 50%;
    width: 100%;
    height: 2px;
    background: var(--md-sys-color-outline);
    z-index: 0;
}

.step-completed:not(:last-child)::after {
    background: var(--md-sys-color-tertiary);
}

.step-number {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: var(--md-sys-color-outline);
    color: var(--md-sys-color-on-surface-variant);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    position: relative;
    z-index: 1;
}

.step-active .step-number {
    background: var(--md-sys-color-primary);
    color: var(--md-sys-color-on-primary);
}

.step-completed .step-number {
    background: var(--md-sys-color-tertiary);
    color: var(--md-sys-color-on-tertiary);
}

.step-label {
    margin-top: var(--md-sys-spacing-2);
    font-size: var(--md-sys-typescale-label-medium-font-size);
    color: var(--md-sys-color-on-surface-variant);
    text-align: center;
}

.step-active .step-label {
    color: var(--md-sys-color-primary);
    font-weight: 500;
}

/* ===== Badges ===== */

.badge {
    display: inline-block;
    padding: var(--md-sys-spacing-1) var(--md-sys-spacing-3);
    border-radius: var(--md-sys-shape-corner-extra-large);
    font-size: var(--md-sys-typescale-label-small-font-size);
    font-weight: 500;
}

.badge-primary {
    background: var(--md-sys-color-primary-container);
    color: var(--md-sys-color-on-primary-container);
}

.badge-success {
    background: var(--md-sys-color-tertiary-container);
    color: var(--md-sys-color-on-tertiary-container);
}

.badge-danger {
    background: var(--md-sys-color-error-container);
    color: var(--md-sys-color-on-error-container);
}

.badge-warning {
    background: var(--md-sys-color-warning-container);
    color: var(--md-sys-color-on-warning-container);
}

/* ===== Empty State ===== */

.empty-state-wrapper {
    text-align: center;
    padding: var(--md-sys-spacing-12);
    background: var(--md-sys-color-surface);
    border-radius: var(--md-sys-shape-corner-large);
    box-shadow: var(--md-sys-shadow-1);
}

.empty-state-icon {
    font-size: 64px;
    margin-bottom: var(--md-sys-spacing-4);
}

.empty-state-title {
    font-size: var(--md-sys-typescale-headline-small-font-size);
    font-weight: 600;
    color: var(--md-sys-color-on-surface);
    margin-bottom: var(--md-sys-spacing-2);
}

.empty-state-description {
    font-size: var(--md-sys-typescale-body-medium-font-size);
    color: var(--md-sys-color-on-surface-variant);
    margin-bottom: var(--md-sys-spacing-6);
}

.empty-state-action {
    display: inline-block;
}

/* ===== Grid Layouts ===== */

.form-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: var(--md-sys-spacing-6);
}

.selection-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--md-sys-spacing-6);
}

.selection-card {
    background: var(--md-sys-color-surface);
    padding: var(--md-sys-spacing-6);
    border-radius: var(--md-sys-shape-corner-large);
    box-shadow: var(--md-sys-shadow-1);
    text-decoration: none;
    color: inherit;
    transition: all 0.2s ease;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    border: 1px solid transparent;
}

.selection-card:hover {
    box-shadow: var(--md-sys-shadow-2);
    transform: translateY(-2px);
    border-color: var(--md-sys-color-primary);
}

.selection-card-icon {
    font-size: 48px;
    margin-bottom: var(--md-sys-spacing-4);
}

.selection-card-title {
    font-size: var(--md-sys-typescale-title-medium-font-size);
    font-weight: 600;
    color: var(--md-sys-color-on-surface);
    margin-bottom: var(--md-sys-spacing-2);
}

.selection-card-description {
    font-size: var(--md-sys-typescale-body-small-font-size);
    color: var(--md-sys-color-on-surface-variant);
}

/* ===== Utility Classes ===== */

.text-center {
    text-align: center;
}

.text-right {
    text-align: right;
}

.text-left {
    text-align: left;
}

.text-muted {
    color: var(--md-sys-color-on-surface-variant);
}

.mt-1 { margin-top: var(--md-sys-spacing-1); }
.mt-2 { margin-top: var(--md-sys-spacing-2); }
.mt-3 { margin-top: var(--md-sys-spacing-3); }
.mt-4 { margin-top: var(--md-sys-spacing-4); }
.mt-5 { margin-top: var(--md-sys-spacing-5); }
.mt-6 { margin-top: var(--md-sys-spacing-6); }
.mt-8 { margin-top: var(--md-sys-spacing-8); }

.mb-1 { margin-bottom: var(--md-sys-spacing-1); }
.mb-2 { margin-bottom: var(--md-sys-spacing-2); }
.mb-3 { margin-bottom: var(--md-sys-spacing-3); }
.mb-4 { margin-bottom: var(--md-sys-spacing-4); }
.mb-5 { margin-bottom: var(--md-sys-spacing-5); }
.mb-6 { margin-bottom: var(--md-sys-spacing-6); }
.mb-8 { margin-bottom: var(--md-sys-spacing-8); }

.p-1 { padding: var(--md-sys-spacing-1); }
.p-2 { padding: var(--md-sys-spacing-2); }
.p-3 { padding: var(--md-sys-spacing-3); }
.p-4 { padding: var(--md-sys-spacing-4); }
.p-5 { padding: var(--md-sys-spacing-5); }
.p-6 { padding: var(--md-sys-spacing-6); }
.p-8 { padding: var(--md-sys-spacing-8); }

.gap-1 { gap: var(--md-sys-spacing-1); }
.gap-2 { gap: var(--md-sys-spacing-2); }
.gap-3 { gap: var(--md-sys-spacing-3); }
.gap-4 { gap: var(--md-sys-spacing-4); }
.gap-6 { gap: var(--md-sys-spacing-6); }
.gap-8 { gap: var(--md-sys-spacing-8); }

.flex { display: flex; }
.flex-col { flex-direction: column; }
.flex-wrap { flex-wrap: wrap; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.justify-start { justify-content: flex-start; }
.justify-end { justify-content: flex-end; }
.align-center { align-items: center; }
.align-start { align-items: flex-start; }
.align-end { align-items: flex-end; }

.w-full { width: 100%; }
.h-full { height: 100%; }
.max-w-sm { max-width: 384px; }
.max-w-md { max-width: 448px; }
.max-w-lg { max-width: 512px; }
.max-w-xl { max-width: 576px; }
.max-w-2xl { max-width: 640px; }

.hidden { display: none; }

/* ===== Responsive ===== */

@media (max-width: 768px) {
    .admin-page-wrapper {
        flex-direction: column;
    }

    .admin-sidebar {
        width: 100%;
        position: static;
        height: auto;
        flex-direction: row;
    }

    .sidebar-nav-menu {
        display: flex;
        gap: var(--md-sys-spacing-2);
        padding: 0;
        flex: 1;
        overflow-x: auto;
    }

    .sidebar-nav-link {
        padding: var(--md-sys-spacing-2) var(--md-sys-spacing-3);
        font-size: var(--md-sys-typescale-label-medium-font-size);
    }

    .admin-main-content {
        margin-left: 0;
        padding: var(--md-sys-spacing-4);
    }

    .form-group-row {
        grid-template-columns: 1fr;
    }

    .stats-grid {
        grid-template-columns: 1fr;
    }

    .form-grid {
        grid-template-columns: 1fr;
    }

    .selection-grid {
        grid-template-columns: 1fr;
    }

    .stepper {
        flex-direction: column;
    }

    .step:not(:last-child)::after {
        display: none;
    }

    .page-header-wrapper {
        flex-direction: column;
        align-items: flex-start;
    }

    .user-topbar {
        flex-direction: column;
        gap: var(--md-sys-spacing-4);
    }

    .modal-dialog {
        width: 95%;
        max-width: 100%;
    }

    .flash-messages-container {
        max-width: 90%;
        right: auto;
        left: var(--md-sys-spacing-2);
    }
}

@media (max-width: 480px) {
    .auth-card-wrapper {
        padding: var(--md-sys-spacing-6);
    }

    .page-container {
        padding: var(--md-sys-spacing-4);
    }

    .admin-main-content {
        padding: var(--md-sys-spacing-4);
    }

    .btn {
        padding: var(--md-sys-spacing-2) var(--md-sys-spacing-4);
        font-size: var(--md-sys-typescale-label-medium-font-size);
    }

    .table-actions {
        flex-direction: column;
    }
}

